+	if (!parent->active_channels) {
 		for (i = 0; i < GS_MAX_RX_URBS; i++) {
 			u8 *buf;
 
@@ -1094,11 +1103,11 @@ static int gs_can_open(struct net_device *netdev)
 out_usb_free_urb:
